import { ChangeDetectorRef, Component, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, Validators, ReactiveFormsModule, FormsModule } from '@angular/forms';
import { finalize } from 'rxjs';
import { RoleService } from '../../core/services/role.service';
import { RoleDto, PermissionDto } from '../../core/models/api.models';

@Component({
  selector: 'app-roles',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule, FormsModule],
  templateUrl: './roles.component.html'
})
export class RolesComponent implements OnInit {
  private cdr = inject(ChangeDetectorRef);
  roles: RoleDto[] = [];
  allPermissions: PermissionDto[] = [];
  rolePermissions: PermissionDto[] = [];
  loading = true;
  saving = false;
  error = '';
  success = '';
  showModal = false;
  showPermModal = false;
  editingRole: RoleDto | null = null;
  selectedRole: RoleDto | null = null;
  form: FormGroup;
  permMap: Record<string, { can_view: boolean; can_add: boolean; can_update: boolean; can_delete: boolean; can_export: boolean }> = {};

  constructor(private roleService: RoleService, private fb: FormBuilder) {
    this.form = this.fb.group({
      role_code: ['', Validators.required],
      role_name: ['', Validators.required]
    });
  }

  ngOnInit(): void {
    this.loadRoles();
    this.roleService.getAllPermissions().subscribe(r => {
      if (r.data) this.allPermissions = r.data;
      this.notifyView();
    });
  }

  loadRoles(): void {
    this.loading = true;
    this.roleService.getAllRoles()
      .pipe(finalize(() => this.finishLoading()))
      .subscribe({
        next: r => {
          if (r.data) this.roles = r.data;
          this.notifyView();
        }
      });
  }

  openCreate(): void {
    this.editingRole = null;
    this.form.reset();
    this.form.get('role_code')?.enable();
    this.showModal = true;
    this.error = '';
  }

  openEdit(role: RoleDto): void {
    this.editingRole = role;
    this.form.patchValue(role);
    this.form.get('role_code')?.disable();
    this.showModal = true;
    this.error = '';
  }

  save(): void {
    if (this.form.invalid) { this.form.markAllAsTouched(); return; }
    this.saving = true;
    this.error = '';
    const obs = this.editingRole
      ? this.roleService.updateRole(this.editingRole.role_id, { role_id: this.editingRole.role_id, role_name: this.form.value.role_name })
      : this.roleService.createRole(this.form.value);

    obs.subscribe({
      next: res => {
        this.saving = false;
        if (res.statusCode === 200) {
          this.success = `Role ${this.editingRole ? 'updated' : 'created'} successfully`;
          this.showModal = false;
          this.loadRoles();
          this.clearSuccessLater();
        } else {
          this.error = res.errorMessage || 'Operation failed';
        }
        this.notifyView();
      },
      error: err => {
        this.saving = false;
        this.error = err?.error?.errorMessage || 'Operation failed';
        this.notifyView();
      }
    });
  }

  openPermissions(role: RoleDto): void {
    this.selectedRole = role;
    this.permMap = {};
    this.allPermissions.forEach(p => {
      this.permMap[p.permission_id] = { can_view: false, can_add: false, can_update: false, can_delete: false, can_export: false };
    });
    this.roleService.getRolePermissions(role.role_id).subscribe(r => {
      if (r.data) {
        r.data.forEach(p => {
          this.permMap[p.permission_id] = {
            can_view: p.can_view, can_add: p.can_add, can_update: p.can_update,
            can_delete: p.can_delete, can_export: p.can_export
          };
        });
      }
      this.notifyView();
    });
    this.showPermModal = true;
  }

  savePermissions(): void {
    if (!this.selectedRole) return;
    this.saving = true;
    const permissionsList = Object.entries(this.permMap).map(([permission_id, perms]) => ({
      role_id: this.selectedRole!.role_id,
      permission_id,
      ...perms
    }));
    this.roleService.updateRolePermissions(this.selectedRole.role_id, { permissionsList }).subscribe({
      next: res => {
        this.saving = false;
        if (res.statusCode === 200) {
          this.success = 'Permissions updated';
          this.showPermModal = false;
          this.clearSuccessLater();
        }
        this.notifyView();
      },
      error: () => {
        this.saving = false;
        this.notifyView();
      }
    });
  }

  get f() { return this.form.controls; }
  get permEntries() { return Object.entries(this.permMap); }
  getPermission(id: string): PermissionDto | undefined { return this.allPermissions.find(p => p.permission_id === id); }

  private finishLoading(): void {
    queueMicrotask(() => {
      this.loading = false;
      this.notifyView();
    });
  }

  private clearSuccessLater(): void {
    setTimeout(() => {
      this.success = '';
      this.notifyView();
    }, 3000);
  }

  private notifyView(): void {
    this.cdr.markForCheck();
  }
}
